def _run_tool_command(self, tool_id):
    """执行工具命令"""
    registry_file = WORKSPACE / "30-scripts-tools" / "tools_registry.json"

    with open(registry_file, 'r', encoding='utf-8') as f:
        registry = json.load(f)

    tool_config = registry.get('tools', {}).get(tool_id)

    if not tool_config:
        return {
            'success': False,
            'error': f"工具未找到：{tool_id}",
            'execution_time_ms': 0
        }

    command = tool_config.get('command')
    if not command:
        return {
            'success': False,
            'error': f"工具无命令配置：{tool_id}",
            'execution_time_ms': 0
        }

    start_time = datetime.now()

    try:
        # 修复中文乱码：使用 chcp 65001 设置 UTF-8 编码
        if sys.platform == 'win32':
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                encoding='utf-8',
                errors='replace',
                timeout=tool_config.get('timeout_seconds', 60),
                env={**os.environ, 'PYTHONIOENCODING': 'utf-8'}
            )
        else:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                encoding='utf-8',
                errors='replace',
                timeout=tool_config.get('timeout_seconds', 60)
            )

        end_time = datetime.now()
        execution_time = (end_time - start_time).total_seconds() * 1000

        # 打印输出（修复乱码）
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

        return {
            'success': result.returncode == 0,
            'returncode': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr,
            'execution_time_ms': execution_time
        }

    except subprocess.TimeoutExpired:
        return {
            'success': False,
            'error': f"工具执行超时 (>{tool_config.get('timeout_seconds', 60)}s)",
            'execution_time_ms': tool_config.get('timeout_seconds', 60) * 1000
        }
    except Exception as e:
        return {
            'success': False,
            'error': str(e),
            'execution_time_ms': 0
        }

